import { readFile, stat } from "node:fs/promises";
import type { Stats } from "node:fs";

export interface DenoFileInfo {
  isFile: boolean;
  isDirectory: boolean;
  isSymlink: boolean;
  size: number;
  mtime: Date;
}

function toInfo(s: Stats): DenoFileInfo {
  return {
    isFile: s.isFile(),
    isDirectory: s.isDirectory(),
    isSymlink: s.isSymbolicLink(),
    size: s.size,
    mtime: s.mtime,
  };
}

export async function denoReadFile(path: string | URL): Promise<Uint8Array> {
  // A plain Uint8Array (not a Buffer) so deep-equality against Uint8Array literals holds.
  return new Uint8Array(await readFile(path));
}

export function denoReadTextFile(path: string | URL): Promise<string> {
  return readFile(path, "utf8");
}

export async function denoStat(path: string | URL): Promise<DenoFileInfo> {
  return toInfo(await stat(path));
}
